mapper.select:
select c.claim_id, c.post_id, c.applicant_id, c.post_owner_id, c.match_id, c.status, c.evidence_text, c.owner_remark, c.applicant_confirmed, c.owner_confirmed, c.accepted_time, c.completed_time, c.create_by, c.create_time, c.update_by, c.update_time, c.version, c.del_flag, p.title as post_title, p.post_type, applicant.nick_name as other_party_name, 'admin' as my_role from lf_claim c join lf_post p on p.post_id = c.post_id left join sys_user applicant on applicant.user_id = c.applicant_id
c.del_flag = '0' and c.status = #{status} and c.post_id = #{postId} and c.applicant_id = #{applicantId} and c.post_owner_id = #{postOwnerId}
order by c.update_time desc, c.claim_id desc
